source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_dividers = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    col_dividers = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    def sections(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    rows, cols = sections(h, row_dividers), sections(w, col_dividers)
    source_panel = max(((r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols),
                       key=lambda p: sum(grid[r][c] != background for r in range(p[0], p[1]) for c in range(p[2], p[3])))
    sr0, sr1, sc0, sc1 = source_panel
    out = [row[:] for row in grid]
    for r0, r1 in rows:
        for c0, c1 in cols:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[sr0 + (r-r0) % (sr1-sr0)][sc0 + (c-c0) % (sc1-sc0)]
    return out
'''
